-- PRS Booking Daily Mock Data Seed Script
-- Generated for year 2025 | 18 zones + ALL_INDIA aggregate

CREATE DATABASE IF NOT EXISTS prs_mock;
USE prs_mock;

DROP TABLE IF EXISTS prs_booking_daily;
CREATE TABLE prs_booking_daily (
    id INT PRIMARY KEY AUTO_INCREMENT,
    booking_date DATE NOT NULL,
    zone_code VARCHAR(20) NOT NULL,
    tickets_booked INT NOT NULL,
    tickets_cancelled INT NOT NULL,
    passengers_booked INT NOT NULL,
    passengers_cancelled INT NOT NULL,
    earning DECIMAL(15,2) NOT NULL,
    refund DECIMAL(15,2) NOT NULL,
    net_earning DECIMAL(15,2) NOT NULL,
    INDEX idx_date (booking_date),
    INDEX idx_zone (zone_code),
    INDEX idx_date_zone (booking_date, zone_code)
);














